#!/usr/bin/env python3
"""Atom-level differential for quantified atoms with nested $ usage."""
import random, sys
sys.path.insert(0, '/app/dev')
import reference
import importlib.util
spec = importlib.util.spec_from_file_location('m', '/app/submission/main.py')
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)

rng = random.Random(2024)
NUM = ('TIME','SIZE','COUNT')

def gen_term(ty, depth, K, fidx, inq, p_dollar):
    cands = [n for n,t in fidx.items() if t == ty]
    opts = ['const'] + (['field'] if cands else []) + \
           (['agg'] if (cands and ty in NUM) else [])
    if depth >= 2 and ty in NUM:
        opts += ['scale','add']
    kind = rng.choice(opts)
    if kind == 'field':
        n = rng.choice(cands)
        if inq and rng.random() < p_dollar:
            at = '$'
        else:
            at = rng.randrange(K)
        return {'field':n,'at':at}
    if kind == 'const':
        if ty in NUM: return {'const':rng.randint(-20,20),'type':ty}
        if ty == 'ID': return {'const':rng.choice(['a','b','c']),'type':'ID'}
        return {'const':rng.choice([True,False]),'type':'FLAG'}
    if kind == 'agg':
        n = rng.choice(cands)
        a = rng.randrange(K); b = rng.randrange(a,K)
        return {'aggregate':rng.choice(['sum','mean','min','max']),'field':n,'from':a,'to':b}
    if kind == 'scale':
        return {'scale':rng.randint(-5,5),'term':gen_term(ty,depth-1,K,fidx,inq,p_dollar)}
    return {'add':[gen_term(ty,depth-1,K,fidx,inq,p_dollar),
                   gen_term(ty,depth-1,K,fidx,inq,p_dollar)]}

bad = 0; total = 0
for trial in range(3000):
    K = rng.randint(1,8)
    fields = []; fidx = {}
    for i in range(rng.randint(1,5)):
        ty = rng.choice(['TIME','SIZE','COUNT','ID','FLAG'])
        nm = 'f%d' % i
        if ty in NUM:
            lo = rng.randint(-9,0); hi = rng.randint(1,9)
            fields.append({'name':nm,'type':ty,'min':lo,'max':hi})
        elif ty == 'ID':
            fields.append({'name':nm,'type':'ID','values':['a','b','c']})
        else:
            fields.append({'name':nm,'type':'FLAG'})
        fidx[nm] = (i,ty)
    rows = []
    for _ in range(K):
        vals = []
        for f in fields:
            if f['type']=='FLAG': vals.append(rng.random()<0.5)
            elif f['type']=='ID': vals.append(rng.choice(f['values']))
            else: vals.append(rng.randint(f['min'],f['max']))
        rows.append(vals)
    avail = [t for (i,t) in fidx.values()]
    ty = rng.choice(avail)
    d = rng.choice([1,2,3,4])
    pd = rng.choice([0.2,0.5,0.9])
    body = {'cmp':rng.choice(['eq','ne','lt','le','gt','ge'] if ty in NUM else ['eq','ne']),
            'left':gen_term(ty,d,K,fidx,True,pd),
            'right':gen_term(ty,d,K,fidx,True,pd)}
    a = rng.randrange(K); b = rng.randrange(a,K)
    atom = {'quantifier':rng.choice(['any','all']),'from':a,'to':b,'predicate':body}
    try:
        f1 = m.compile_atom(atom, K, fidx)
    except Exception as e:
        print('MAIN FAIL', atom, repr(e)); bad += 1; continue
    try:
        f2 = reference.mk_atom(atom, K, fidx)
    except Exception as e:
        print('REF FAIL', atom, repr(e)); bad += 1; continue
    v1 = f1(rows); v2 = f2(rows)
    total += 1
    if bool(v1) != bool(v2):
        print('MISMATCH', atom, v1, v2, rows); bad += 1
        if bad > 5: break
print('compared', total, 'bad', bad)
